package ma.lias.controller;
import ma.lias.entity.*; import ma.lias.repository.AnnualReportRepository; import ma.lias.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.Year; import java.util.*;
@RestController @RequestMapping({"/api/reports", "/api/annual-reports"})
public class AnnualReportController { private final AnnualReportRepository repo; private final ReportService service; private final AuditService audit; public AnnualReportController(AnnualReportRepository repo, ReportService service, AuditService audit){this.repo=repo;this.service=service;this.audit=audit;} @GetMapping public List<AnnualReport> all(){return repo.findAll();} @PostMapping("/generate") @PreAuthorize("hasAnyRole('DIRECTOR','ADMIN')") public AnnualReport generate(@RequestParam(required=false) Integer year, @RequestBody(required=false) Map<String,Object> body, org.springframework.security.core.Authentication auth) throws Exception { Integer selectedYear = year; if(selectedYear==null && body!=null && body.get("year")!=null) selectedYear = Integer.parseInt(String.valueOf(body.get("year"))); Long uid = auth!=null && auth.getPrincipal() instanceof User u ? u.getId() : null; AnnualReport r=service.generate(selectedYear==null? Year.now().getValue():selectedYear, uid); audit.log("GENERATE","AnnualReport",r.getId(),"Rapport annuel"); return r; } }
